#!/usr/bin/env bash
#
# generate.sh - materialise the synthetic multi-repository Java fixture used by the
# unified project knowledge library tests.
#
# Usage:
#   bash generate.sh [target-dir]
#
# target-dir defaults to "$PWD/.agent-work/knowledge-fixtures". The target directory is
# DELETED and recreated on every run.
#
# The generator is deterministic and idempotent: every fixture commit uses a fixed
# author/committer identity, a fixed timestamp and fixed commit messages, so repeated
# runs into different directories produce identical commit SHAs and byte-identical
# fixture-manifest.json files (the only environment-dependent value in the manifest is
# the absolute repository path).
#
# Generated layout:
#   <target>/common           shared contract library, released as com.example:common:1.4.2
#   <target>/order-service    publishes OrderCancelledEvent, depends on common 1.4.2
#   <target>/device-service   consumes OrderCancelledEvent, depends on common 2.0.0
#   <target>/fixture-manifest.json
#
# Determinism rail: the fixture repositories intentionally have no .gitignore, and the
# global/system git configuration (including core.excludesFile, commit.gpgsign and any
# init.defaultBranch) is neutralised below so that commit SHAs do not depend on the
# machine that runs the generator.

set -euo pipefail

FIXED_DATE='2026-01-02T03:04:05+00:00'
FIXED_GENERATED_AT='2026-01-02T03:04:05+00:00'
MANIFEST_NOTES='Synthetic fixture material generated by testdata/knowledge-fixtures/generate.sh for knowledge-library tests. It is not real project data, is not derived from any production repository, and must not be treated as project truth.'

TARGET="${1:-$PWD/.agent-work/knowledge-fixtures}"

case "$TARGET" in
  ''|'/'|'.'|'..')
    printf 'generate.sh: refusing to use %s as the fixture target\n' "${TARGET:-<empty>}" >&2
    exit 2
    ;;
esac
if [ -e "$TARGET/.git" ]; then
  printf 'generate.sh: refusing to delete %s because it contains a .git directory\n' "$TARGET" >&2
  exit 2
fi

umask 022

# Deterministic git environment: fixed identity, fixed timestamps, no ambient config.
export GIT_AUTHOR_NAME=fixture
export GIT_AUTHOR_EMAIL=fixture@example.invalid
export GIT_AUTHOR_DATE="$FIXED_DATE"
export GIT_COMMITTER_NAME=fixture
export GIT_COMMITTER_EMAIL=fixture@example.invalid
export GIT_COMMITTER_DATE="$FIXED_DATE"
export GIT_CONFIG_NOSYSTEM=1
export GIT_CONFIG_GLOBAL=/dev/null
export GIT_TERMINAL_PROMPT=0
export TZ=UTC
export LC_ALL=C

write_file() {
  local path="$1"
  mkdir -p "$(dirname "$path")"
  cat > "$path"
}

init_repo() {
  local repo="$1"
  mkdir -p "$repo"
  if ! git -C "$repo" init -q -b main >/dev/null 2>&1; then
    # git < 2.28 has no "init -b".
    git -C "$repo" init -q >/dev/null 2>&1
    git -C "$repo" symbolic-ref HEAD refs/heads/main
  fi
  git -C "$repo" config user.name fixture
  git -C "$repo" config user.email fixture@example.invalid
  git -C "$repo" config core.autocrlf false
  git -C "$repo" config core.safecrlf false
  git -C "$repo" config core.excludesFile /dev/null
  git -C "$repo" config commit.gpgsign false
  git -C "$repo" config tag.gpgsign false
  git -C "$repo" config advice.detachedHead false
}

commit_repo() {
  local repo="$1"
  local message="$2"
  git -C "$repo" add -A
  GIT_AUTHOR_NAME=fixture \
  GIT_AUTHOR_EMAIL=fixture@example.invalid \
  GIT_AUTHOR_DATE="$FIXED_DATE" \
  GIT_COMMITTER_NAME=fixture \
  GIT_COMMITTER_EMAIL=fixture@example.invalid \
  GIT_COMMITTER_DATE="$FIXED_DATE" \
    git -C "$repo" commit -q -m "$message"
}

json_string() {
  local s="$1"
  s="${s//\\/\\\\}"
  s="${s//\"/\\\"}"
  printf '"%s"' "$s"
}

untracked_json_array() {
  local repo="$1"
  local out=''
  local line
  while IFS= read -r line; do
    [ -n "$line" ] || continue
    out="${out}${out:+, }$(json_string "$line")"
  done < <(git -C "$repo" ls-files --others --exclude-standard | LC_ALL=C sort)
  printf '[%s]' "$out"
}

MANIFEST_REPOS=''
REPO_INDEX=0

emit_repo() {
  local name="$1"
  local kind="$2"
  local artifact="$3"
  local consumer="$4"
  local repo="$TARGET/$name"
  local head branch count status_out dirty untracked_json

  head="$(git -C "$repo" rev-parse HEAD)"
  branch="$(git -C "$repo" rev-parse --abbrev-ref HEAD)"
  count="$(git -C "$repo" rev-list --count HEAD)"
  status_out="$(git -C "$repo" status --porcelain)"
  if [ -n "$status_out" ]; then
    dirty=true
  else
    dirty=false
  fi
  untracked_json="$(untracked_json_array "$repo")"

  REPO_INDEX=$((REPO_INDEX + 1))
  if [ "$REPO_INDEX" -gt 1 ]; then
    MANIFEST_REPOS="${MANIFEST_REPOS},"
  fi
  MANIFEST_REPOS="${MANIFEST_REPOS}
    {
      \"name\": $(json_string "$name"),
      \"kind\": $(json_string "$kind"),
      \"path\": $(json_string "$repo"),
      \"branch\": $(json_string "$branch"),
      \"head_commit\": $(json_string "$head"),
      \"commit_count\": ${count},
      \"dirty\": ${dirty},
      \"untracked\": ${untracked_json},
      \"artifact\": $(json_string "$artifact"),
      \"consumer\": $(json_string "$consumer")
    }"
}

rm -rf -- "$TARGET"
mkdir -p -- "$TARGET"

COMMON="$TARGET/common"
ORDER="$TARGET/order-service"
DEVICE="$TARGET/device-service"

##############################################################################
# common - shared contract library (kind: common)
##############################################################################

init_repo "$COMMON"

write_file "$COMMON/pom.xml" <<'XML'
