write_file "$COMMON/src/main/java/com/example/common/event/OrderCancelledEvent.java" <<'JAVA'
package com.example.common.event;

import java.time.Instant;
import java.util.Objects;

/**
 * Domain event published when an order is cancelled.
 *
 * <p>This type is the shared contract between order-service (producer) and
 * device-service (consumer). Both services compile against this artifact, so an
 * incompatible change here is a breaking change for every consumer.</p>
 *
 * <p>The topic name lives in {@link #TOPIC} so that producer and consumer cannot
 * drift apart silently.</p>
 */
public final class OrderCancelledEvent {

    /** Kafka topic carrying this event; both the producer and the consumer reference it. */
    public static final String TOPIC = "order.cancelled";

    private final String orderId;
    private final String deviceId;
    private final String reason;
    private final Instant cancelledAt;

    public OrderCancelledEvent(String orderId, String deviceId, String reason, Instant cancelledAt) {
        this.orderId = Objects.requireNonNull(orderId, "orderId");
        this.deviceId = Objects.requireNonNull(deviceId, "deviceId");
        this.reason = reason == null ? "unspecified" : reason;
        this.cancelledAt = cancelledAt == null ? Instant.EPOCH : cancelledAt;
    }

    public String orderId() {
        return orderId;
    }

    public String deviceId() {
        return deviceId;
    }

    public String reason() {
        return reason;
    }

    public Instant cancelledAt() {
        return cancelledAt;
    }

    @Override
    public String toString() {
        return "OrderCancelledEvent{orderId='" + orderId + "', deviceId='" + deviceId
                + "', reason='" + reason + "', cancelledAt=" + cancelledAt + '}';
    }
}
JAVA

write_file "$COMMON/src/main/java/com/example/common/messaging/EventPublisher.java" <<'JAVA'
package com.example.common.messaging;

import com.example.common.event.OrderCancelledEvent;

/**
 * Transport-agnostic port for publishing domain events.
 *
 * <p>Services depend on this interface rather than on a broker client so that the
 * messaging transport can be replaced in tests.</p>
 */
public interface EventPublisher {

    /**
     * Publishes an event to an explicit topic.
     *
     * @param topic destination topic
     * @param event event payload
     * @param <T>   event type
     */
    <T> void publish(String topic, T event);

    /**
     * Publishes an event to the topic registered for its type.
     *
     * @param event event payload
     * @param <T>   event type
     */
    default <T> void publish(T event) {
        publish(topicFor(event), event);
    }

    /**
     * Resolves the topic that carries the given event type.
     *
     * @param event event payload
     * @return the destination topic
     */
    static String topicFor(Object event) {
        if (event instanceof OrderCancelledEvent) {
            return OrderCancelledEvent.TOPIC;
        }
        throw new IllegalArgumentException("no topic registered for " + event.getClass().getName());
    }
}
JAVA

write_file "$COMMON/README.md" <<'MD'
# common

Shared contract library for the example platform. Published to the internal Maven
repository as `com.example:common`.

## Responsibilities

- Domain event payloads shared between services, for example
  `com.example.common.event.OrderCancelledEvent`.
- Messaging ports (interfaces) that services depend on instead of a broker client,
  for example `com.example.common.messaging.EventPublisher`.
- Serialization-stable field names, because every consumer of an event reads them.

## Consumers

| Service | Declared version of `common` |
| --- | --- |
| `order-service` | `1.4.2` |
| `device-service` | `2.0.0` |

The released artifact in this repository is `1.4.2`. The `2.0.0` dependency declared by
`device-service` therefore does not exist here; that skew is intentional fixture data.

## Boundaries

This library has no service-specific logic, no Spring beans and no direct dependency on
a broker client. Anything that needs a running broker belongs in a service.
MD

