write_file "$ORDER/src/main/java/com/example/order/Order.java" <<'JAVA'
package com.example.order;

import java.time.Instant;

/**
 * Aggregate root for a customer order.
 *
 * <p>An order is bound to at most one device; cancelling the order must therefore
 * release the reservation that device-service holds for it.</p>
 */
public final class Order {

    /** Lifecycle states of an order; only CREATED and CONFIRMED can be cancelled. */
    public enum State {
        CREATED,
        CONFIRMED,
        CANCELLED
    }

    private final String id;
    private final String deviceId;
    private State state;
    private Instant cancelledAt;

    public Order(String id, String deviceId, State state) {
        this.id = id;
        this.deviceId = deviceId;
        this.state = state;
    }

    public String id() {
        return id;
    }

    public String deviceId() {
        return deviceId;
    }

    public State state() {
        return state;
    }

    public Instant cancelledAt() {
        return cancelledAt;
    }

    /**
     * Rejects cancellation of an order that already reached the CANCELLED state.
     *
     * @throws IllegalStateException when the order is not cancellable
     */
    public void validateCancellable() {
        if (state == State.CANCELLED) {
            throw new IllegalStateException("order " + id + " is already cancelled");
        }
    }

    public void markCancelled(Instant when) {
        this.state = State.CANCELLED;
        this.cancelledAt = when;
    }
}
