write_file "$ORDER/src/main/java/com/example/order/OrderService.java" <<'JAVA'
package com.example.order;

import com.example.common.event.OrderCancelledEvent;
import com.example.common.messaging.EventPublisher;
import java.time.Instant;
import java.util.Objects;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Cancellation use cases for order-service.
 *
 * <p>{@link #cancelOrder(String, String)} is the only producer of
 * {@link OrderCancelledEvent} in the platform: it validates the aggregate state,
 * persists the cancellation and then publishes the event that device-service
 * consumes in order to release the device reservation.</p>
 */
@Service
public class OrderService {

    private final OrderRepository orderRepository;
    private final EventPublisher eventPublisher;

    public OrderService(OrderRepository orderRepository, EventPublisher eventPublisher) {
        this.orderRepository = Objects.requireNonNull(orderRepository, "orderRepository");
        this.eventPublisher = Objects.requireNonNull(eventPublisher, "eventPublisher");
    }

    /**
     * Cancels an order and publishes {@link OrderCancelledEvent}.
     *
     * @param orderId identifier of the order to cancel
     * @param reason  free-text cancellation reason
     * @return the event that was published
     * @throws OrderNotFoundException when the order does not exist
     * @throws IllegalStateException  when the order is already cancelled
     */
    @Transactional
    public OrderCancelledEvent cancelOrder(String orderId, String reason) {
        Objects.requireNonNull(orderId, "orderId");

        Order order = orderRepository.findById(orderId)
                .orElseThrow(() -> new OrderNotFoundException(orderId));

        // State validation first: a terminal order must not be cancelled twice.
        order.validateCancellable();
        order.markCancelled(Instant.now());
        orderRepository.save(order);

        OrderCancelledEvent event = new OrderCancelledEvent(
                order.id(), order.deviceId(), reason, order.cancelledAt());
        eventPublisher.publish(OrderCancelledEvent.TOPIC, event);
        return event;
    }
}
JAVA

write_file "$ORDER/src/main/java/com/example/order/api/OrderCancelController.java" <<'JAVA'
package com.example.order.api;

import com.example.common.event.OrderCancelledEvent;
import com.example.order.OrderService;
import java.time.Instant;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

/** REST entry point for order cancellation. */
@RestController
public class OrderCancelController {

    private final OrderService orderService;

    public OrderCancelController(OrderService orderService) {
        this.orderService = orderService;
    }

    /**
     * {@code POST /orders/{id}/cancel}
     *
     * <p>Accepts the cancellation and returns the published event payload with 202,
     * because the device reservation is released asynchronously by device-service.</p>
     */
    @PostMapping(path = "/orders/{id}/cancel", consumes = MediaType.APPLICATION_JSON_VALUE,
            produces = MediaType.APPLICATION_JSON_VALUE)
    public ResponseEntity<CancelOrderResponse> cancelOrder(@PathVariable("id") String orderId,
                                                           @RequestBody CancelOrderRequest request) {
        OrderCancelledEvent event = orderService.cancelOrder(orderId, request.reason());
        CancelOrderResponse body = new CancelOrderResponse(
                event.orderId(), event.deviceId(), event.reason(), event.cancelledAt());
        return ResponseEntity.accepted().body(body);
    }

    /** Request body of {@code POST /orders/{id}/cancel}. */
    public record CancelOrderRequest(String reason) {
    }

    /** Response body of {@code POST /orders/{id}/cancel}. */
    public record CancelOrderResponse(String orderId, String deviceId, String reason, Instant cancelledAt) {
    }
}
