write_file "$ORDER/src/main/java/com/example/order/config/OrderEventProducerConfig.java" <<'JAVA'
package com.example.order.config;

import com.example.common.event.OrderCancelledEvent;
import java.util.HashMap;
import java.util.Map;
import org.apache.kafka.clients.producer.ProducerConfig;
import org.apache.kafka.common.serialization.StringSerializer;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.kafka.core.DefaultKafkaProducerFactory;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.kafka.core.ProducerFactory;
import org.springframework.kafka.support.serializer.JsonSerializer;

/**
 * Producer-side Kafka wiring for order-service.
 *
 * <p>order-service only writes to the bus: this module declares no message listener.
 * The consumer of {@link OrderCancelledEvent} lives in device-service, which
 * subscribes to {@link #ORDER_CANCELLED_TOPIC}.</p>
 */
@Configuration
public class OrderEventProducerConfig {

    /** Topic carrying {@link OrderCancelledEvent}; mirrors {@link OrderCancelledEvent#TOPIC}. */
    public static final String ORDER_CANCELLED_TOPIC = "order.cancelled";

    @Value("${spring.kafka.bootstrap-servers:kafka:9092}")
    private String bootstrapServers;

    @Bean
    public ProducerFactory<String, Object> orderProducerFactory() {
        Map<String, Object> props = new HashMap<>();
        props.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, bootstrapServers);
        props.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class);
        props.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, JsonSerializer.class);
        props.put(ProducerConfig.ACKS_CONFIG, "all");
        props.put(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG, Boolean.TRUE);
        return new DefaultKafkaProducerFactory<>(props);
    }

    @Bean
    public KafkaTemplate<String, Object> orderKafkaTemplate(ProducerFactory<String, Object> orderProducerFactory) {
        return new KafkaTemplate<>(orderProducerFactory);
    }
}
