package com.example.device;

/**
 * A device held for an order until the order completes or is cancelled.
 */
public final class DeviceReservation {

    /** Lifecycle states of a reservation. */
    public enum State {
        HELD,
        RELEASED
    }

    private final String orderId;
    private final String deviceId;
    private State state;

    public DeviceReservation(String orderId, String deviceId, State state) {
        this.orderId = orderId;
        this.deviceId = deviceId;
        this.state = state;
    }

    public String orderId() {
        return orderId;
    }

    public String deviceId() {
        return deviceId;
    }

    public State state() {
        return state;
    }

    /**
     * Moves the reservation to RELEASED.
     *
     * @throws IllegalStateException when the reservation was already released
     */
    public void markReleased() {
        if (state == State.RELEASED) {
            throw new IllegalStateException("reservation for order " + orderId + " is already released");
        }
        this.state = State.RELEASED;
    }
}
