package com.example.device;

import java.util.Objects;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Releases device reservations.
 *
 * <p>{@link #releaseReservation(String, String, String)} is called by
 * {@link DeviceReservationConsumer} for every cancellation event that order-service
 * publishes on the order.cancelled topic.</p>
 */
@Service
public class DeviceReservationService {

    /** Attempts made before a failed release is parked for manual review. */
    public static final int RELEASE_RETRY_ATTEMPTS = 3;

    private final DeviceReservationRepository reservationRepository;

    public DeviceReservationService(DeviceReservationRepository reservationRepository) {
        this.reservationRepository = Objects.requireNonNull(reservationRepository, "reservationRepository");
    }

    /**
     * Frees the reservation held for the cancelled order.
     *
     * <p>Releasing an already released reservation is a no-op so that at-least-once
     * delivery of the cancellation event stays idempotent.</p>
     *
     * @param orderId  order whose reservation is released
     * @param deviceId device that was reserved for the order
     * @param reason   cancellation reason carried by the event
     */
    @Transactional
    public void releaseReservation(String orderId, String deviceId, String reason) {
        Objects.requireNonNull(orderId, "orderId");

        DeviceReservation reservation = reservationRepository.findByOrderId(orderId)
                .orElseThrow(() -> new IllegalStateException("no reservation for order " + orderId));

        if (reservation.state() == DeviceReservation.State.RELEASED) {
            return;
        }

        reservation.markReleased();
        reservationRepository.save(reservation);
    }
}
