package com.example.device;

import com.example.common.event.OrderCancelledEvent;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.stereotype.Component;

/**
 * Consumes {@link OrderCancelledEvent} messages published by order-service on the
 * {@link OrderCancelledEvent#TOPIC} topic and frees the device reservation that was
 * held for the cancelled order.
 */
@Component
public class DeviceReservationConsumer {

    private static final Logger LOG = LoggerFactory.getLogger(DeviceReservationConsumer.class);

    private final DeviceReservationService reservationService;

    public DeviceReservationConsumer(DeviceReservationService reservationService) {
        this.reservationService = reservationService;
    }

    /**
     * Handles an order cancellation coming from order-service.
     *
     * @param event cancellation payload shared through com.example:common
     */
    @KafkaListener(topics = OrderCancelledEvent.TOPIC, groupId = "${spring.kafka.consumer.group-id}")
    public void onOrderCancelled(OrderCancelledEvent event) {
        LOG.info("handling OrderCancelledEvent for order {} (device {})", event.orderId(), event.deviceId());
        reservationService.releaseReservation(event.orderId(), event.deviceId(), event.reason());
    }
}
