package com.example.device;

/**
 * Retry policy for reservation releases.
 *
 * <p>Untracked fixture file: it is written after the final commit and deliberately
 * left untracked so the knowledge library has to ingest uncommitted work-in-progress
 * source.</p>
 */
public final class ReleaseRetryPolicy {

    /** Maximum release attempts before the reservation is parked for manual review. */
    public static final int MAX_ATTEMPTS = 5;

    /** Base backoff between attempts, in milliseconds. */
    public static final long BACKOFF_MILLIS = 250L;

    private ReleaseRetryPolicy() {
    }

    /**
     * Exponential backoff for the given attempt number.
     *
     * @param attempt 1-based attempt number
     * @return milliseconds to wait before the next attempt
     */
    public static long backoffMillis(int attempt) {
        return BACKOFF_MILLIS * (1L << Math.max(0, attempt - 1));
    }
}
